const occasionKey = { Weddings: "weddings", Festivals: "festivals", Gifts: "gifts", "Daily Wear": "dailyWear", "Home Decor": "homeDecor", Traditional: "traditional", "Corporate Gifts": "corporateGifts" };

function textFor(value, lang) { return typeof value === "object" ? (value?.[lang] || value?.en || "") : value || ""; }
function tContent(value, lang) { return textFor(value, lang); }
function titleOf(product, lang) { return textFor(product.title || product.name, lang); }
function regionOf(name, t) { return t(regionKey[name] || name); }
function craftOf(name, t) { return t(craftKey[name] || name); }
function localizedRaw(value, t, lang) {
  const keyMap = {
    "India":"india", "Product":"product", "Traditional handwork":"traditionalHandwork",
    "Cotton":"cotton", "Terracotta":"terracotta", "Brass":"brass", "Sheesham Wood":"sheeshamWood",
    "Indigo":"indigo", "Magenta":"magenta", "Gold":"gold", "Maroon":"maroon", "Cream":"cream", "Rust":"rust", "Earth":"earth", "Walnut":"walnut", "Amber":"amber", "Wine":"wine", "Antique Gold":"antiqueGold", "handloom":"handloom", "ikat":"ikat", "cotton":"cotton", "telangana":"telangana", "pottery":"pottery", "handmade":"handmade", "terracotta":"terracotta", "wood":"wood", "carving":"carving", "decor":"decor", "jewellery":"jewellery", "brass":"brass", "kalamkari":"kalamkari", "painting":"painting", "textile":"textile", "embroidery":"embroidery"
  };
  const k = keyMap[value];
  return k ? t(k) : textFor(value, lang);
}

const LangContext = createContext({
  lang: "en",
  setLang: () => {},
  t: (key) => locales.en?.[key] ?? key
});
function useLang() {
  return useContext(LangContext);
}
function LangProvider({ children }) {
  const [lang, setLang] = useState(() => { try { return localStorage.getItem("kalaudaan-language") || "en"; } catch { return "en"; } });
  const changeLang = (next) => { const safe = supportedLanguages.includes(next) ? next : "en"; setLang(safe); try { localStorage.setItem("kalaudaan-language", safe); } catch {} document.documentElement.lang = safe; };
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  useEffect(() => { const onStorage = (e) => { if (e.key === "kalaudaan-language" && supportedLanguages.includes(e.newValue)) setLang(e.newValue); }; window.addEventListener("storage", onStorage); return () => window.removeEventListener("storage", onStorage); }, []);
  const value = useMemo(() => ({ lang, setLang: changeLang, t: (key) => locales[lang]?.[key] ?? locales.en[key] ?? ({ cotton: lang === "te" ? "పత్తి" : lang === "hi" ? "कपास" : "Cotton", terracotta: lang === "te" ? "టెర్రాకోట" : lang === "hi" ? "टेराकोटा" : "Terracotta", brass: lang === "te" ? "ఇత్తడి" : lang === "hi" ? "पीतल" : "Brass", sheeshamWood: lang === "te" ? "శీషం చెక్క" : lang === "hi" ? "शीशम लकड़ी" : "Sheesham Wood", indigo: lang === "te" ? "ఇండిగో" : lang === "hi" ? "इंडिगो" : "Indigo", magenta: lang === "te" ? "మెజెంటా" : lang === "hi" ? "मैजेंटा" : "Magenta", gold: lang === "te" ? "బంగారం" : lang === "hi" ? "सोना" : "Gold", maroon: lang === "te" ? "మెరూన్" : lang === "hi" ? "मैरून" : "Maroon", cream: lang === "te" ? "క్రీమ్" : lang === "hi" ? "क्रीम" : "Cream", rust: lang === "te" ? "తుప్పు రంగు" : lang === "hi" ? "जंग रंग" : "Rust", earth: lang === "te" ? "మట్టి రంగు" : lang === "hi" ? "मिट्टी" : "Earth", walnut: lang === "te" ? "వాల్‌నట్" : lang === "hi" ? "अखरोट" : "Walnut", amber: lang === "te" ? "అంబర్" : lang === "hi" ? "ऐंबर" : "Amber", wine: lang === "te" ? "వైన్" : lang === "hi" ? "वाइन" : "Wine", antiqueGold: lang === "te" ? "పురాతన బంగారం" : lang === "hi" ? "एंटीक गोल्ड" : "Antique Gold" })[key] ?? key }), [lang]);
  return <LangContext.Provider value={value}>{children}</LangContext.Provider>;
}

function useToast() {
  const [toast, setToast] = useState("");
  const timer = useRef(null);
  const show = (message) => { setToast(message); clearTimeout(timer.current); timer.current = setTimeout(() => setToast(""), 2400); };
  return { toast, show };
}

class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: false }; }
  static getDerivedStateFromError() { return { error: true }; }
  render() { if (this.state.error) return <div className="error-screen"><ShieldCheck size={42}/><h1>{this.props.t?.("empty") || "Something went wrong"}</h1><button className="gold-btn" onClick={() => window.location.reload()}><RefreshCcw size={16}/> Reload</button></div>; return this.props.children; }
}

