function Reveal({ children, className = "" }) { const ref = useRef(null); const [visible, setVisible] = useState(false); useEffect(() => { const el = ref.current; if (!el) return; const obs = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setVisible(true); obs.disconnect(); } }, { threshold: .12 }); obs.observe(el); return () => obs.disconnect(); }, []); return <div ref={ref} className={`reveal ${visible ? "is-visible" : ""} ${className}`}>{children}</div>; }
